question:
What problem can occur with the following code?

struct DetailView: View {
    @ObservedObject var viewModel = ViewModel()
    var body: some View { Text(viewModel.title) }
}

Why does the following code fail to compile?

struct Fruit {
    var name: String
}
let fruits = [Fruit(name: "Apple"), Fruit(name: "Pear")]

List(fruits) { fruit in
    Text(fruit.name)
}

What is true about the following code?

class CounterModel: ObservableObject {
    @Published var count = 0
    func increment() {
        count += 1
    }
}

A row view is defined like this and used inside a `List`:
```
class Fetcher: ObservableObject {
    @Published var data = "empty"
}
struct RowView: View {
    @ObservedObject var fetcher = Fetcher()
    var body: some View { Text(fetcher.data) }
}
```
Every time the parent view re-renders, `RowView`'s initializer runs again. What is the practical bug here, and how should it be fixed?

```
struct DetailView: View {
    @EnvironmentObject var settings: Settings
    var body: some View { Text(settings.name) }
}
struct ContentView: View {
    var body: some View {
        NavigationLink("Go", destination: DetailView())
    }
}
```
`Settings` is never provided via `.environmentObject(...)` anywhere in the view hierarchy. What happens when `DetailView` appears?

```
struct Item: Identifiable {
    var id: UUID { UUID() }
    var name: String
}
```
This `Item` is used as the data for a `ForEach` inside a `List`. What problem does this `id` implementation cause?

```
struct EditorView: View {
    @State private var items = ["A", "B", "C"]
    var body: some View {
        List {
            ForEach(items.indices, id: \.self) { index in
                TextField("Item", text: $items[index])
                    .swipeActions {
                        Button("Delete") { items.remove(at: index) }
                    }
            }
        }
    }
}
```
Swiping to delete a row in the middle of the list can cause a crash. Why?

```
struct ProfileView: View {
    @StateObject private var viewModel: ProfileViewModel
    init(userID: String) {
        _viewModel = StateObject(wrappedValue: ProfileViewModel(userID: userID))
    }
    var body: some View { Text(viewModel.userID) }
}
```
A parent view recreates `ProfileView(userID:)` with a new `userID` in response to a state change, but the displayed `userID` never updates. Why?

```
class ViewModel: ObservableObject {
    @Published var count = 0
    var cancellable: AnyCancellable?
    init() {
        cancellable = timerPublisher.sink { [self] _ in
            self.count += 1
        }
    }
    deinit { print("ViewModel deinit") }
}
```
This view model's `deinit` never prints, even after every view referencing it disappears. What is the most likely cause?
